"""Generate the skills index with the legacy PowerShell text contract."""

from __future__ import annotations

import argparse
import io
import re
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import TextIO

REPO_ROOT = Path(__file__).resolve().parents[2]
PREFIX = "[skills-index]"
HEADER = (
    "<!-- DO NOT EDIT - generated by tooling~/scripts/generate-skills-index.ps1. -->\n"
    "<!-- Regenerate: pwsh -NoProfile -File tooling~/scripts/generate-skills-index.ps1 -->\n"
    "\n# Skills Index\n\n"
    "Agent Skills ([SKILL.md format](https://agentskills.io)) for specific tasks. "
    "Invoke a skill by reading its SKILL.md when the task matches.\n"
)
SECTIONS = (
    ("Core", "Core Skills (Always Consider)"),
    ("Performance", "Performance Skills"),
    ("Feature", "Feature Skills"),
)
# .NET whitespace excludes the four information separators Python includes.
WHITESPACE = r"[^\S\x1c-\x1f]"
TOP_PAIR = re.compile(rf"^([A-Za-z0-9_-]+):{WHITESPACE}*(.*)$")
CHILD_PAIR = re.compile(rf"^{WHITESPACE}+([A-Za-z0-9_-]+):{WHITESPACE}*(.*)$")
VALUE_QUOTES = re.compile(r'''^(["'])(.*)\1$''')
# PowerShell's empty-string comparison ignores non-whitespace ASCII controls.
EMPTY_MAPPING = re.compile(r"^[\x00-\x08\x0e-\x1f\x7f]*$")
Frontmatter = dict[str, str | dict[str, str]]


@dataclass(frozen=True)
class SkillEntry:
    name: str
    description: str
    category: str


def trim(value: str) -> str:
    """Match String.Trim without splitting Unicode line separators."""
    return re.sub(rf"^{WHITESPACE}+|{WHITESPACE}+$", "", value)


def read_lines(path: Path) -> list[str]:
    """StreamReader detects BOMs; ReadAllLines splits only CR and LF."""
    data = path.read_bytes()
    encoding = "utf-8-sig"
    if data.startswith((b"\xff\xfe\x00\x00", b"\x00\x00\xfe\xff")):
        encoding = "utf-32"
    elif data.startswith((b"\xff\xfe", b"\xfe\xff")):
        encoding = "utf-16"
    text = data.decode(encoding, errors="replace")
    return re.split(r"\r\n|\r|\n", text)


def frontmatter(path: Path) -> Frontmatter | None:
    lines = read_lines(path)
    if len(lines) < 3 or lines[0] != "---":
        return None
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None
    values: Frontmatter = {}
    in_metadata = False
    for line in lines[1:end]:
        if line and not re.match(WHITESPACE, line):
            in_metadata = False
            match = TOP_PAIR.match(line)
            if match:
                key, value = match.groups()
                value = trim(value)
                if EMPTY_MAPPING.fullmatch(value):
                    values[key.lower()] = {}
                    in_metadata = True
                else:
                    values[key.lower()] = VALUE_QUOTES.sub(r"\2", value)
        elif in_metadata:
            match = CHILD_PAIR.match(line)
            metadata = values.get("metadata")
            if match and isinstance(metadata, dict):
                key, value = match.groups()
                metadata[key.lower()] = VALUE_QUOTES.sub(r"\2", trim(value))
    return values


def ordinal_key(value: str) -> bytes:
    """StringComparer.Ordinal compares UTF-16 units, not Unicode scalars."""
    return value.encode("utf-16-be", errors="surrogatepass")


def index_content(skills_dir: Path, *, verbose_output: bool = False,
                  stream: TextIO = sys.stdout) -> str:
    entries: list[SkillEntry] = []
    for directory in sorted(skills_dir.iterdir(), key=lambda path: ordinal_key(path.name)):
        if not directory.is_dir() or directory.name.startswith("."):
            continue
        skill_file = directory / "SKILL.md"
        if not skill_file.exists():
            continue
        values = frontmatter(skill_file)
        if values is None:
            if verbose_output:
                stream.write(f"{PREFIX} No frontmatter in {directory.name}/SKILL.md - skipping\n")
            continue
        description = values.get("description")
        if not isinstance(description, str) or not trim(description):
            if verbose_output:
                stream.write(f"{PREFIX} No description in {directory.name}/SKILL.md - skipping\n")
            continue
        category = "Feature"
        metadata = values.get("metadata")
        if isinstance(metadata, dict):
            category = metadata.get("category", category)
        entries.append(SkillEntry(directory.name, description, category))
    parts = [HEADER]
    for category, title in SECTIONS:
        items = [entry for entry in entries if entry.category.lower() == category.lower()]
        if not items:
            continue
        parts.append(f"\n## {title}\n\n| Skill | When to Use |\n| --- | --- |\n")
        for entry in sorted(items, key=lambda item: ordinal_key(item.name)):
            parts.append(f"| [{entry.name}](./{entry.name}/SKILL.md) | {entry.description} |\n")
    return "".join(parts)


def generate_skills_index(repo_root: Path, *, output_path: Path | None = None,
                          stdout: bool = False, verbose_output: bool = False,
                          stream: TextIO = sys.stdout,
                          diagnostic_stream: TextIO | None = None) -> int:
    diagnostics = diagnostic_stream if diagnostic_stream is not None else (sys.stderr if stdout else stream)
    skills_dir = repo_root / ".llm" / "skills"
    if not skills_dir.exists():
        diagnostics.write(f"{PREFIX} ERROR: Skills directory not found at: {skills_dir}\n")
        return 1
    destination = output_path or skills_dir / "index.md"
    content = index_content(skills_dir, verbose_output=verbose_output, stream=diagnostics)
    if stdout:
        stream.write(content)
    else:
        destination.write_bytes(content.encode("utf-8"))
        if verbose_output:
            diagnostics.write(f"{PREFIX} Wrote {destination}\n")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", type=Path, default=REPO_ROOT)
    parser.add_argument("--output-path", type=Path)
    parser.add_argument("--stdout", action="store_true")
    parser.add_argument("--verbose-output", action="store_true")
    args = parser.parse_args(argv)
    return generate_skills_index(args.repo_root, output_path=args.output_path,
                                 stdout=args.stdout, verbose_output=args.verbose_output)


if __name__ == "__main__":
    # Redirected stdout keeps UTF-8 and LF on Windows as well as Unix.
    if isinstance(sys.stdout, io.TextIOWrapper):
        sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    if isinstance(sys.stderr, io.TextIOWrapper):
        sys.stderr.reconfigure(encoding="utf-8", newline="\n")
    sys.exit(main())
